    "dsl": "timeline \"Acme — First Five Years\"\nconfig: style = lollipop\n\n2020-06: \"Founders meet at Y Combinator\" [side: below]\n2020-11: milestone \"Incorporation + pre-seed $1M\" [side: above, color: #1565C0]\n2021-04: \"First engineer hired\" [side: below]\n2021-09: milestone \"Product beta — 50 design partners\" [side: above, color: #2E7D32]\n2022-03: milestone \"Seed round — $6M\" [side: above, color: #1565C0]\n2022-11: \"Team reaches 20 people\" [side: below]\n2023-05: milestone \"Platform v1 GA\" [side: above, color: #6A1B9A]\n2023-10: milestone \"Series A — $22M\" [side: above, color: #1565C0]\n2024-06: \"100th enterprise customer\" [side: below]\n2025-01: milestone \"Platform v2 launched\" [side: above, color: #6A1B9A]",
